{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE vahdam_db.maplemonk.vahdam_amazon_pnl_overall_fy27_onwards AS ( WITH asin_map_unpivot AS ( SELECT TRIM(asin) AS asin, src, BRAND AS brand, \"Common SKU ID\" AS common_sku_id, \"Common SKU Description\" AS common_sku_description, CATEGORY AS category, \"Sub-category\" AS sub_category FROM vahdam_db.maplemonk.VAHDAM_FY27_INPUTS_PRODUCT_MAPPING UNPIVOT (asin FOR src IN ( \"Amazon USA\",\"Amazon CA\",\"Amazon DE\",\"Amazon ES\",\"Amazon FR\",\"Amazon IT\", \"Amazon UK\",\"Amazon UAE\",\"Amazon AUS\",\"Amazon JP\",\"Amazon SG\",\"Amazon India\", \"Amazon US 1P\",\"Amazon UK 1P\",\"Amazon EU 1P\",\"Amazon CA 1P\",\"Amazon India 1P\" )) WHERE asin IS NOT NULL AND TRIM(asin) <> \'\' ), asin_geo_map AS ( SELECT asin, brand, common_sku_id, common_sku_description, category, sub_category, CASE WHEN src ILIKE \'%1P\' THEN \'Amazon_1P\' ELSE \'Amazon_3P\' END AS channel, CASE WHEN UPPER(src)=\'AMAZON USA\' THEN \'USA\' WHEN UPPER(src)=\'AMAZON US 1P\' THEN \'USA\' WHEN UPPER(src)=\'AMAZON INDIA\' THEN \'IN\' WHEN UPPER(src)=\'AMAZON INDIA 1P\' THEN \'IN\' ELSE UPPER(REPLACE(REPLACE(src,\'Amazon \',\'\'),\' 1P\',\'\')) END AS geo FROM asin_map_unpivot WHERE UPPER(src) <> \'AMAZON EU 1P\' UNION ALL SELECT m.asin, m.brand, m.common_sku_id, m.common_sku_description, m.category, m.sub_category, \'Amazon_1P\' AS channel, g.geo FROM asin_map_unpivot m CROSS JOIN (SELECT \'DE\' geo UNION ALL SELECT \'ES\' UNION ALL SELECT \'FR\' UNION ALL SELECT \'IT\') g WHERE UPPER(m.src) = \'AMAZON EU 1P\' ), asin_geo_map_dedup AS ( SELECT asin, channel, geo, ANY_VALUE(brand) AS brand, ANY_VALUE(common_sku_id) AS common_sku_id, ANY_VALUE(common_sku_description) AS common_sku_description, ANY_VALUE(category) AS category, ANY_VALUE(sub_category) AS sub_category FROM asin_geo_map GROUP BY asin, channel, geo ), cogs_sheet AS ( SELECT TRIM(MATERIAL) AS common_sku_id, TRY_TO_DECIMAL(REPLACE(COGS,\',\',\'\'),30,5) AS cogs_per_unit_inr FROM vahdam_db.maplemonk.VAHDAM_FY27_INPUTS_COGS_SHEET WHERE MATERIAL IS NOT NULL ), cogs_budget_csku AS ( SELECT TRIM(\"Common SKU\") AS common_sku_id, AVG( TRY_TO_DECIMAL(REPLACE(COGS_PER_UNIT,\',\',\'\'),30,5) * TRY_TO_DECIMAL(REPLACE(FX,\',\',\'\'),30,5) ) AS cogs_per_unit_inr_csku FROM vahdam_db.maplemonk.VAHDAM_BUDGET_AMAZON_3P___1P_BUDGET WHERE TRIM(\"Common SKU\") IS NOT NULL AND TRIM(\"Common SKU\") <> \'\' GROUP BY TRIM(\"Common SKU\") HAVING AVG( TRY_TO_DECIMAL(REPLACE(COGS_PER_UNIT,\',\',\'\'),30,5) * TRY_TO_DECIMAL(REPLACE(FX,\',\',\'\'),30,5) ) IS NOT NULL ), settlement_latest AS ( SELECT ASIN, UPPER(GEO) AS geo, CASE WHEN NULLIF(UNITS,0) IS NULL THEN NULL ELSE FBA_FEES/UNITS END AS lastmile_per_unit_local_settlement, CASE WHEN NULLIF(SALES,0) IS NULL THEN NULL ELSE COMMISSION/SALES END AS commission_pct_settlement FROM (SELECT s.*, ROW_NUMBER() OVER (PARTITION BY s.ASIN, UPPER(s.GEO) ORDER BY s.DATE DESC) rn FROM vahdam_db.maplemonk.AMAZON_3P_SETTLEMENT s WHERE UPPER(s.CHANNEL)=\'AMAZON 3P\') WHERE rn=1 ), budget_raw AS ( SELECT TRIM(ASIN) AS asin, TRIM(\"Common SKU\") AS common_sku_id, UPPER(GEOGRAPHY) AS geo, CASE WHEN UPPER(PLATFORM) LIKE \'%1P%\' THEN \'Amazon_1P\' WHEN UPPER(PLATFORM) LIKE \'%3P%\' THEN \'Amazon_3P\' ELSE PLATFORM END AS channel, TRY_TO_DATE(\"MONTH\",\'DD-Mon-YY\') AS month_start, TRY_TO_DECIMAL(REPLACE(FX,\',\',\'\'),30,5) AS fx, TRY_TO_DECIMAL(REPLACE(QTY,\',\',\'\'),30,5) AS qty, TRY_TO_DECIMAL(REPLACE(\"Net Sales\",\',\',\'\'),30,5) AS net_sales, TRY_TO_DECIMAL(REPLACE(COGS,\',\',\'\'),30,5) AS cogs, TRY_TO_DECIMAL(REPLACE(\"Additional Duty\",\',\',\'\'),30,5) AS additional_duty, TRY_TO_DECIMAL(REPLACE(COMMISSION,\',\',\'\'),30,5) AS commission, TRY_TO_DECIMAL(REPLACE(OUTBOUND,\',\',\'\'),30,5) AS outbound, TRY_TO_DECIMAL(REPLACE(\"3PL\",\',\',\'\'),30,5) AS three_pl, TRY_TO_DECIMAL(REPLACE(STORAGE,\',\',\'\'),30,5) AS storage, TRY_TO_DECIMAL(REPLACE(\"Last mile\",\',\',\'\'),30,5) AS last_mile, TRY_TO_DECIMAL(REPLACE(\"Performance Marketing\",\',\',\'\'),30,5) AS performance_marketing, TRY_TO_DECIMAL(REPLACE(COGS_PER_UNIT,\',\',\'\'),30,5) AS cogs_per_unit_local, TRY_TO_DECIMAL(REPLACE(OUTBOUND_PER_UNIT,\',\',\'\'),30,5) AS outbound_per_unit_local, TRY_TO_DECIMAL(REPLACE(\"3pl_per_unit\",\',\',\'\'),30,5) AS three_pl_per_unit_local, TRY_TO_DECIMAL(REPLACE(STORAGE_PER_UNIT,\',\',\'\'),30,5) AS storage_per_unit_local, TRY_TO_DECIMAL(REPLACE(LASTMILE_PER_UNIT,\',\',\'\'),30,5) AS lastmile_per_unit_local, TRY_TO_DECIMAL(REPLACE(COMMISSION_PER_UNIT,\',\',\'\'),30,5) AS commission_per_unit_local, TRY_TO_DECIMAL(REPLACE(ADDITIONAL_DUTY_PER_UNIT,\',\',\'\'),30,5) AS additional_duty_per_unit_local FROM vahdam_db.maplemonk.VAHDAM_BUDGET_AMAZON_3P___1P_BUDGET ), fx_map AS ( SELECT geo, month_start, MAX(fx) AS fx FROM budget_raw WHERE fx IS NOT NULL AND month_start IS NOT NULL GROUP BY geo, month_start ), fx_geo_avg AS (SELECT geo, AVG(fx) AS fx_geo_avg FROM fx_map GROUP BY geo), geo_currency AS ( SELECT UPPER(GEO) AS geo, ANY_VALUE(CURRENCY) AS currency_local FROM vahdam_db.maplemonk.VAHDAM_AMAZON_SALES_MARKETING WHERE CURRENCY IS NOT NULL AND TRIM(CURRENCY) <> \'\' GROUP BY UPPER(GEO) ), budget_asin AS ( SELECT geo, channel, month_start, asin, ANY_VALUE(common_sku_id) AS common_sku_id, MAX(fx) AS fx, SUM(qty) AS qty, SUM(net_sales) AS net_sales_local, SUM(cogs) AS cogs_local, SUM(additional_duty) AS additional_duty_local, SUM(commission) AS commission_local, SUM(outbound) AS outbound_local, SUM(three_pl) AS three_pl_local, SUM(storage) AS storage_local, SUM(last_mile) AS last_mile_local, SUM(performance_marketing) AS pm_spend_local, AVG(cogs_per_unit_local) AS cogs_per_unit_local, AVG(outbound_per_unit_local) AS outbound_per_unit_local, AVG(three_pl_per_unit_local) AS three_pl_per_unit_local, AVG(storage_per_unit_local) AS storage_per_unit_local, AVG(lastmile_per_unit_local) AS lastmile_per_unit_local, AVG(commission_per_unit_local) AS commission_per_unit_local, AVG(additional_duty_per_unit_local) AS additional_duty_per_unit_local, CASE WHEN NULLIF(SUM(net_sales),0) IS NULL THEN NULL ELSE SUM(commission)/NULLIF(SUM(net_sales),0) END AS commission_pct_budget_asin, CASE WHEN COALESCE(SUM(additional_duty),0) > 0 OR COALESCE(AVG(additional_duty_per_unit_local),0) > 0 THEN 1 ELSE 0 END AS has_additional_duty_flag FROM budget_raw WHERE month_start IS NOT NULL AND asin IS NOT NULL GROUP BY geo, channel, month_start, asin ), budget_pkg AS ( SELECT geo, channel, month_start, LEFT(common_sku_id,6) AS pkg6, ANY_VALUE(outbound_per_unit_local) AS outbound_per_unit_local_pkg, ANY_VALUE(lastmile_per_unit_local) AS lastmile_per_unit_local_pkg, ANY_VALUE(three_pl_per_unit_local) AS three_pl_per_unit_local_pkg, ANY_VALUE(storage_per_unit_local) AS storage_per_unit_local_pkg FROM budget_raw WHERE month_start IS NOT NULL AND common_sku_id IS NOT NULL AND LENGTH(common_sku_id) >= 6 GROUP BY geo, channel, month_start, LEFT(common_sku_id,6) ), budget_days AS ( SELECT month_start, DAY(LAST_DAY(month_start)) AS days_in_month FROM (SELECT DISTINCT month_start FROM budget_raw WHERE month_start IS NOT NULL) ), day_offsets AS (SELECT SEQ4() AS d_off FROM TABLE(GENERATOR(ROWCOUNT => 31))), budget_daily AS ( SELECT DATEADD(day, o.d_off, b.month_start) AS day, b.channel, b.geo, b.asin, b.qty/NULLIF(d.days_in_month,0) AS qty_budget, b.net_sales_local/NULLIF(d.days_in_month,0) AS sales_budget_local, b.cogs_local/NULLIF(d.days_in_month,0) AS cogs_budget_local, b.additional_duty_local/NULLIF(d.days_in_month,0) AS additional_duty_budget_local, b.commission_local/NULLIF(d.days_in_month,0) AS commission_budget_local, b.outbound_local/NULLIF(d.days_in_month,0) AS outbound_budget_local, b.three_pl_local/NULLIF(d.days_in_month,0) AS three_pl_budget_local, b.storage_local/NULLIF(d.days_in_month,0) AS storage_budget_local, b.last_mile_local/NULLIF(d.days_in_month,0) AS last_mile_budget_local, b.pm_spend_local/NULLIF(d.days_in_month,0) AS pm_spend_budget_local FROM budget_asin b JOIN budget_days d ON d.month_start=b.month_start JOIN day_offsets o ON o.d_off<d.days_in_month ), actuals AS ( SELECT DAY AS day, CASE WHEN UPPER(MARKETPLACE)=\'AMAZON_1P\' THEN \'Amazon_1P\' WHEN UPPER(MARKETPLACE)=\'AMAZON_3P\' THEN \'Amazon_3P\' ELSE MARKETPLACE END AS channel, UPPER(GEO) AS geo, ASIN AS asin, ANY_VALUE(CURRENCY) AS currency_local, SUM(QUANTITY) AS qty_actual, SUM(SALES) AS sales_actual_local, SUM(SPEND) AS pm_spend_actual_local FROM vahdam_db.maplemonk.VAHDAM_AMAZON_SALES_MARKETING GROUP BY DAY, MARKETPLACE, UPPER(GEO), ASIN ), universe AS ( SELECT day,channel,geo,asin FROM actuals UNION SELECT day,channel,geo,asin FROM budget_daily ), asin_resolved AS ( SELECT u.day, u.channel, u.geo, u.asin, m.brand, m.common_sku_id, m.common_sku_description, m.category, m.sub_category, LEFT(m.common_sku_id, 6) AS pkg6 FROM universe u LEFT JOIN asin_geo_map_dedup m ON m.asin = u.asin AND m.channel = u.channel AND m.geo = u.geo ), pass1 AS ( SELECT u.day, u.channel, u.geo, u.asin, ar.brand, ar.common_sku_id, ar.common_sku_description, ar.category, ar.sub_category, ar.pkg6, DATE_TRUNC(\'MONTH\', u.day) AS month_start, COALESCE( fxm.fx, fxg.fx_geo_avg, CASE WHEN gc.currency_local=\'INR\' OR u.geo=\'IN\' THEN 1 END ) AS fx_inr, a.currency_local, a.qty_actual, a.sales_actual_local, a.pm_spend_actual_local, cbc.cogs_per_unit_inr_csku, cs.cogs_per_unit_inr AS cogs_sheet_inr, COALESCE(cbc.cogs_per_unit_inr_csku, cs.cogs_per_unit_inr * 1.05) AS cogs_per_unit_inr_p1, ba.outbound_per_unit_local AS ba_out_pu, bp.outbound_per_unit_local_pkg AS bp_out_pu, COALESCE(ba.outbound_per_unit_local, bp.outbound_per_unit_local_pkg) AS outbound_per_unit_local_p1, COALESCE(ba.three_pl_per_unit_local, bp.three_pl_per_unit_local_pkg) AS three_pl_per_unit_local_p1, COALESCE(ba.storage_per_unit_local, bp.storage_per_unit_local_pkg) AS storage_per_unit_local_p1, CASE WHEN u.channel=\'Amazon_3P\' AND sl.lastmile_per_unit_local_settlement IS NOT NULL THEN sl.lastmile_per_unit_local_settlement WHEN ba.lastmile_per_unit_local IS NOT NULL THEN ba.lastmile_per_unit_local ELSE NULL END AS lastmile_per_unit_local_p1, CASE WHEN u.channel=\'Amazon_3P\' AND sl.commission_pct_settlement IS NOT NULL THEN sl.commission_pct_settlement WHEN ba.commission_pct_budget_asin IS NOT NULL THEN ba.commission_pct_budget_asin ELSE NULL END AS commission_pct_p1, COALESCE(ba.has_additional_duty_flag, 0) AS has_additional_duty_flag, bd.qty_budget, bd.sales_budget_local, bd.cogs_budget_local, bd.additional_duty_budget_local, bd.commission_budget_local, bd.outbound_budget_local, bd.three_pl_budget_local, bd.storage_budget_local, bd.last_mile_budget_local, bd.pm_spend_budget_local FROM universe u LEFT JOIN asin_resolved ar ON ar.day=u.day AND ar.channel=u.channel AND ar.geo=u.geo AND ar.asin=u.asin LEFT JOIN actuals a ON a.day=u.day AND a.channel=u.channel AND a.geo=u.geo AND a.asin=u.asin LEFT JOIN budget_daily bd ON bd.day=u.day AND bd.channel=u.channel AND bd.geo=u.geo AND bd.asin=u.asin LEFT JOIN cogs_sheet cs ON cs.common_sku_id=ar.common_sku_id LEFT JOIN cogs_budget_csku cbc ON cbc.common_sku_id=ar.common_sku_id LEFT JOIN settlement_latest sl ON sl.asin=u.asin AND sl.geo=u.geo LEFT JOIN fx_map fxm ON fxm.geo=u.geo AND fxm.month_start=DATE_TRUNC(\'MONTH\',u.day) LEFT JOIN fx_geo_avg fxg ON fxg.geo=u.geo LEFT JOIN geo_currency gc ON gc.geo=u.geo LEFT JOIN budget_asin ba ON ba.geo=u.geo AND ba.channel=u.channel AND ba.month_start=DATE_TRUNC(\'MONTH\',u.day) AND ba.asin=u.asin LEFT JOIN budget_pkg bp ON bp.geo=u.geo AND bp.channel=u.channel AND bp.month_start=DATE_TRUNC(\'MONTH\',u.day) AND bp.pkg6=ar.pkg6 ), actuals_pct AS ( SELECT geo, channel, month_start, CASE WHEN SUM(CASE WHEN cogs_per_unit_inr_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local*fx_inr END)>0 THEN SUM(CASE WHEN cogs_per_unit_inr_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN qty_actual*cogs_per_unit_inr_p1 END) / NULLIF(SUM(CASE WHEN cogs_per_unit_inr_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local*fx_inr END),0) END AS cogs_pct_actual, CASE WHEN SUM(CASE WHEN outbound_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END)>0 THEN SUM(CASE WHEN outbound_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN qty_actual*outbound_per_unit_local_p1 END) / NULLIF(SUM(CASE WHEN outbound_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END),0) END AS outbound_pct_actual, CASE WHEN SUM(CASE WHEN three_pl_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END)>0 THEN SUM(CASE WHEN three_pl_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN qty_actual*three_pl_per_unit_local_p1 END) / NULLIF(SUM(CASE WHEN three_pl_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END),0) END AS three_pl_pct_actual, CASE WHEN SUM(CASE WHEN storage_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END)>0 THEN SUM(CASE WHEN storage_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN qty_actual*storage_per_unit_local_p1 END) / NULLIF(SUM(CASE WHEN storage_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END),0) END AS storage_pct_actual, CASE WHEN SUM(CASE WHEN lastmile_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END)>0 THEN SUM(CASE WHEN lastmile_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN qty_actual*lastmile_per_unit_local_p1 END) / NULLIF(SUM(CASE WHEN lastmile_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END),0) END AS lastmile_pct_actual, CASE WHEN SUM(CASE WHEN commission_pct_p1 IS NOT NULL AND sales_actual_local IS NOT NULL THEN sales_actual_local END)>0 THEN SUM(CASE WHEN commission_pct_p1 IS NOT NULL AND sales_actual_local IS NOT NULL THEN sales_actual_local*commission_pct_p1 END) / NULLIF(SUM(CASE WHEN commission_pct_p1 IS NOT NULL AND sales_actual_local IS NOT NULL THEN sales_actual_local END),0) END AS commission_pct_actual FROM pass1 GROUP BY geo, channel, month_start ), final AS ( SELECT p.day, p.channel, p.geo, p.asin, p.brand, p.common_sku_id, p.common_sku_description, p.category, p.sub_category, p.month_start, p.fx_inr, p.currency_local, p.qty_actual, p.sales_actual_local, p.pm_spend_actual_local, COALESCE(p.cogs_per_unit_inr_p1, p.sales_actual_local*p.fx_inr*ap.cogs_pct_actual/NULLIF(p.qty_actual,0)) AS cogs_per_unit_inr_used, COALESCE(p.outbound_per_unit_local_p1, p.sales_actual_local*ap.outbound_pct_actual/NULLIF(p.qty_actual,0)) AS outbound_per_unit_local_used, COALESCE(p.three_pl_per_unit_local_p1, p.sales_actual_local*ap.three_pl_pct_actual/NULLIF(p.qty_actual,0)) AS three_pl_per_unit_local_used, COALESCE(p.storage_per_unit_local_p1, p.sales_actual_local*ap.storage_pct_actual/NULLIF(p.qty_actual,0)) AS storage_per_unit_local_used, COALESCE(p.lastmile_per_unit_local_p1, p.sales_actual_local*ap.lastmile_pct_actual/NULLIF(p.qty_actual,0)) AS lastmile_per_unit_local_used, COALESCE(p.commission_pct_p1, ap.commission_pct_actual) AS commission_pct_used, p.has_additional_duty_flag, CASE WHEN p.cogs_per_unit_inr_csku IS NOT NULL THEN \'N\' ELSE \'Y\' END AS cogs_fallback, CASE WHEN p.ba_out_pu IS NOT NULL THEN \'N\' ELSE \'Y\' END AS outbound_fallback, p.qty_budget, p.sales_budget_local, p.cogs_budget_local, p.additional_duty_budget_local, p.commission_budget_local, p.outbound_budget_local, p.three_pl_budget_local, p.storage_budget_local, p.last_mile_budget_local, p.pm_spend_budget_local FROM pass1 p LEFT JOIN actuals_pct ap ON ap.geo=p.geo AND ap.channel=p.channel AND ap.month_start=p.month_start ) SELECT day, channel, geo, asin, brand, common_sku_id, common_sku_description, category, sub_category, currency_local, fx_inr, qty_actual, sales_actual_local, qty_actual * cogs_per_unit_inr_used / NULLIF(fx_inr,0) AS cogs_actual_local, CASE WHEN has_additional_duty_flag = 1 THEN COALESCE(sales_actual_local,0) * 0.10 * 0.32 ELSE 0 END AS additional_duty_actual_l